268:         LocalDate hoje = clock.instant().atZone(fuso).toLocalDate();
269:         if (inicio.toLocalTime().getMinute() % 15 != 0 || inicio.toLocalTime().getSecond() != 0
270:                 || inicio.toLocalTime().getNano() != 0 || inicio.toLocalDate().isBefore(hoje)
271:                 || inicio.toLocalDate().isAfter(hoje.plusDays(60))) {
272:             throw new IllegalArgumentException("inicio fora da grade ou do horizonte de 60 dias");
273:         }
274:         var ids = atendimentos.buscarIdsOcupacao(List.of(p.getId()), inicio.toLocalDate().atStartOfDay(),
275:                 inicio.toLocalDate().plusDays(1).atStartOfDay());
276:         List<Ocupacao> ocupacoes = atendimentos.findAllById(ids).stream()
277:                 .filter(a -> !a.getId().equals(ignorarId))
278:                 .map(a -> new Ocupacao(a.getInicio(), a.getDuracaoMinutos(), a.getIntervaloMinutos())).toList();
279:         if (!horarios.calcular(inicio.toLocalDate(), fuso, clock.instant(),
280:                 janelas.calcular(p, inicio.toLocalDate()), ocupacoes, duracao, intervalo).contains(inicio)) {
