294:                 return clientes.saveAndFlush(novo);
295:             });
296:         }
297:         boolean id = pedido.clienteId() != null;
298:         boolean nome = pedido.clienteNome() != null;
299:         if (id == nome) throw new IllegalArgumentException("informe clienteId ou clienteNome");
300:         if (id) {
