public record ClienteResumo(String nome, String telefoneContato) {}
public record ResumoPainel(long proximosAtivos, long realizados, long cancelados) {}
public record PainelResposta(Instant agora, ClienteResumo cliente, Resposta proximo,
        List<Resposta> proximos, List<Resposta> historico, ResumoPainel resumo) {}

@Transactional(readOnly = true)
public PainelResposta painel(int limiteProximos, int limiteHistorico) {
    UsuarioPrincipal sessao = atual.get();
    if (sessao.perfil() != PerfilUsuario.CLIENTE) throw new AccessDeniedException("acesso negado");
    if (limiteProximos < 1 || limiteProximos > 20 || limiteHistorico < 1 || limiteHistorico > 20) {
        throw new IllegalArgumentException("limites devem estar entre 1 e 20");
    }
    Instant agora = clock.instant();
    Usuario autor = usuarios.findById(sessao.id()).orElseThrow();
    ClienteResumo dados = new ClienteResumo(autor.getNome(), autor.getTelefoneContato());
    var clienteOpt = clientes.findByUsuarioId(sessao.id());
    if (clienteOpt.isEmpty()) {
        return new PainelResposta(agora, dados, null, List.of(), List.of(), new ResumoPainel(0,0,0));
    }
    Cliente cliente = clienteOpt.get();
    List<Atendimento> todos = atendimentos.findByClienteId(cliente.getId());
    record Item(Atendimento atendimento, Instant instante, boolean futuro, boolean cancelado) {}
    List<Item> itens = todos.stream().map(a -> {
        Instant instante = a.getInicio().atZone(ZoneId.of(a.getFusoHorarioAgendamento())).toInstant();
        boolean cancelado = a.getStatus() == AtendimentoStatus.CANCELADO;
        boolean futuro = !cancelado && instante.isAfter(agora);
        return new Item(a, instante, futuro, cancelado);
    }).toList();
    List<Item> proximos = itens.stream().filter(Item::futuro).sorted(Comparator.comparing(Item::instante)).limit(limiteProximos).toList();
    List<Item> historico = itens.stream().filter(i -> i.cancelado() || !i.futuro()).sorted(Comparator.comparing(Item::instante).reversed()).limit(limiteHistorico).toList();
    long realizados = itens.stream().filter(i -> !i.cancelado() && !i.futuro()).count();
    long cancelados = itens.stream().filter(Item::cancelado).count();
    List<Resposta> proximosResp = proximos.stream().map(i -> resposta(i.atendimento(), sessao)).toList();
    List<Resposta> historicoResp = historico.stream().map(i -> resposta(i.atendimento(), sessao)).toList();
    Resposta proximo = proximosResp.isEmpty() ? null : proximosResp.get(0);
    return new PainelResposta(agora, dados, proximo, proximosResp, historicoResp,
            new ResumoPainel(proximos.size(), realizados, cancelados));
}
```
